package ai.nexusone.specification; import ai.nexusone.entity.AutonomousEnterpriseValueRealization; import ai.nexusone.enums.*; import org.springframework.data.jpa.domain.Specification; public final class AutonomousEnterpriseValueRealizationSpecification {private AutonomousEnterpriseValueRealizationSpecification(){} public static Specification<AutonomousEnterpriseValueRealization> filter(String k, AutonomousEnterpriseValueRealizationPriority p, AutonomousEnterpriseValueRealizationStatus s){return(root, q, cb)->{var x=cb.conjunction();if(k!=null&&!k.isBlank())x=cb.and(x,cb.like(cb.lower(root.get("title")),"%"+k.toLowerCase()+"%"));if(p!=null)x=cb.and(x,cb.equal(root.get("priority"),p));if(s!=null)x=cb.and(x,cb.equal(root.get("status"),s));return x;};}}